using Microsoft.EntityFrameworkCore;
using MKSANCrud.Data;
namespace MKSANCrud.Services.Database;
public sealed class DatabaseSchemaV34Initializer(MKSANContext db) {
 public const string Sql="""
CREATE TABLE IF NOT EXISTS "MedicoesPiloto" (
 "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "Data" date NOT NULL, "Periodo" varchar(10) NOT NULL, "Revisao" integer NOT NULL, "Desconsiderada" boolean NOT NULL DEFAULT false,
 "Realizadas" integer NOT NULL, "Faltas" integer NOT NULL, "Canceladas" integer NOT NULL, "SemDesfecho" integer NOT NULL,
 "MinutosAgendados" integer NULL, "MinutosDisponiveis" integer NULL, "MinutosRecepcao" integer NULL,
 "CustoHoraRecepcao" numeric(12,2) NULL, "Fonte" varchar(300) NOT NULL, "Motivo" varchar(300) NOT NULL,
 "AgendaHash" varchar(64) NULL, "RegistradoEm" timestamptz NOT NULL, "RegistradoPor" text NOT NULL,
 CONSTRAINT "CK_MedicoesPiloto_Valores" CHECK (
  "Periodo" IN ('Antes','Piloto') AND "Revisao">0 AND
  "Realizadas" BETWEEN 0 AND 100000 AND "Faltas" BETWEEN 0 AND 100000 AND "Canceladas" BETWEEN 0 AND 100000 AND "SemDesfecho" BETWEEN 0 AND 100000 AND
  ("MinutosAgendados" IS NULL OR "MinutosAgendados" BETWEEN 0 AND 144000) AND
  ("MinutosDisponiveis" IS NULL OR "MinutosDisponiveis" BETWEEN 0 AND 144000) AND
  ("MinutosRecepcao" IS NULL OR "MinutosRecepcao" BETWEEN 0 AND 144000) AND
  ("CustoHoraRecepcao" IS NULL OR "CustoHoraRecepcao" BETWEEN 0 AND 10000)));
CREATE UNIQUE INDEX IF NOT EXISTS "IX_MedicoesPiloto_Periodo_Data_Revisao" ON "MedicoesPiloto" ("Periodo","Data","Revisao");
CREATE OR REPLACE FUNCTION callmed_medicao_piloto_imutavel() RETURNS trigger LANGUAGE plpgsql AS $$
 BEGIN RAISE EXCEPTION 'Medição publicada é imutável; registre uma revisão.'; END; $$;
DROP TRIGGER IF EXISTS "TR_MedicoesPiloto_Imutavel" ON "MedicoesPiloto";
CREATE TRIGGER "TR_MedicoesPiloto_Imutavel" BEFORE UPDATE OR DELETE ON "MedicoesPiloto"
 FOR EACH ROW EXECUTE FUNCTION callmed_medicao_piloto_imutavel();
""";
 public Task AplicarAsync(CancellationToken ct=default)=>db.Database.ExecuteSqlRawAsync(Sql,ct);
}
